unit.script:
message("Target down. Next: the pair behind the low wall to the north - perfect for a grenade.");
objective("Grenade the pair behind the wall: press the Frag Grenade button (or its number), click a tile near them to aim, click again to throw");
show_zone("grenade_spot", true);

tile.script:
show_zone("cover_spot", false);
message("Good: the shield icons show cover. Half cover (low walls) blocks some shots, full cover (tall walls) more.");
objective("Shoot the dummy: click it to AIM (odds appear by the cursor), then click again or press Space to FIRE");

mission.script:
if unit_team(unit) == "enemy" && alive_count("enemy") == 0 && flag("trained") == 0 {
  set_flag("trained", 1);
  message("Range clear! Tip: Overwatch (2) makes a soldier shoot the first enemy that moves in sight; Hunker Down (3) adds defence and calms fear.");
  objective("Walk any soldier onto the green EVAC pad (south-east)");
  show_zone("evac", true);
}
